files.Cargo.toml:
[workspace]
members = ["crates/*"]
resolver = "2"

[workspace.package]
# Please update rustfmt.toml when bumping the Rust edition
edition = "2024"
rust-version = "1.97"
homepage = "https://docs.astral.sh/ruff"
documentation = "https://docs.astral.sh/ruff"
repository = "https://github.com/astral-sh/ruff"
authors = ["Charlie Marsh <charlie.r.marsh@gmail.com>"]
license = "MIT"

[workspace.dependencies]
char_str = { version = "0.0.4", default-features = false, features = ["std"] }
ruff = { version = "0.17.0", path = "crates/ruff" }
ruff_annotate_snippets = { version = "0.0.17", path = "crates/ruff_annotate_snippets" }
ruff_cache = { version = "0.0.17", path = "crates/ruff_cache" }
ruff_command_line = { version = "0.0.17", path = "crates/ruff_command_line" }
ruff_db = { version = "0.0.17", path = "crates/ruff_db", default-features = false }
ruff_diagnostics = { version = "0.0.17", path = "crates/ruff_diagnostics" }
ruff_formatter = { version = "0.0.17", path = "crates/ruff_formatter" }
ruff_graph = { version = "0.0.17", path = "crates/ruff_graph" }
ruff_index = { version = "0.0.17", path = "crates/ruff_index" }
ruff_linter = { version = "0.17.0", path = "crates/ruff_linter" }
ruff_macros = { version = "0.0.17", path = "crates/ruff_macros" }
ruff_markdown = { version = "0.0.17", path = "crates/ruff_markdown" }
ruff_memory_usage = { version = "0.0.17", path = "crates/ruff_memory_usage" }
ruff_notebook = { version = "0.0.17", path = "crates/ruff_notebook" }
ruff_options_metadata = { version = "0.0.17", path = "crates/ruff_options_metadata" }
ruff_python_ast = { version = "0.0.17", path = "crates/ruff_python_ast" }
ruff_python_codegen = { version = "0.0.17", path = "crates/ruff_python_codegen" }
ruff_python_edits = { version = "0.0.17", path = "crates/ruff_python_edits" }
ruff_python_formatter = { version = "0.0.17", path = "crates/ruff_python_formatter" }
