unicode-normalization = { version = "0.1.23", default-features = false, features = ["std"] }
unicode-width = { version = "0.2.0", default-features = false }
url = { version = "2.5.0", default-features = false, features = ["std"] }
uuid = { version = "1.6.1", default-features = false, features = ["std"] }
walkdir = { version = "2.3.2", default-features = false }
wasm-bindgen = { version = "0.2.92", default-features = false, features = ["std"] }
wasm-bindgen-test = { version = "0.3.42", default-features = false, features = ["std"] }
which = { version = "8.0.0", default-features = false, features = ["real-sys"] }
wild = { version = "2", default-features = false }
